CREATE OR REPLACE FUNCTION public.ensure_current_user()
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public AS $$
DECLARE v_auth uuid:=auth.uid(); v_id bigint;
BEGIN
  IF v_auth IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  SELECT users_id INTO v_id FROM public.users WHERE auth_user_id=v_auth;
  IF v_id IS NULL THEN
    INSERT INTO public.users(auth_user_id,status_id) VALUES(v_auth,1)
    ON CONFLICT(auth_user_id) DO UPDATE SET auth_user_id=excluded.auth_user_id
    RETURNING users_id INTO v_id;
  END IF;
  RETURN v_id;
END; $$;

INSERT INTO public.status(status_id,status_name,status_created_at,status_updated_at) VALUES
(1,'ativo',now(),now()),(2,'inativo',now(),now()),(3,'pendente',now(),now()),(4,'processando',now(),now()),
(5,'concluido',now(),now()),(6,'erro',now(),now()),(7,'cancelado',now(),now()),(8,'pausado',now(),now())
ON CONFLICT(status_id) DO UPDATE SET status_name=excluded.status_name;
INSERT INTO public.lead_status(lead_status_id,lead_status_name,lead_status_created_at,lead_status_updated_at) VALUES
(1,'importado',now(),now()),(2,'validado',now(),now()),(3,'pre_envio',now(),now()),(4,'na_fila',now(),now()),
(5,'enviado',now(),now()),(6,'invalido',now(),now()),(7,'duplicado',now(),now()),(8,'arquivado',now(),now())
ON CONFLICT(lead_status_id) DO UPDATE SET lead_status_name=excluded.lead_status_name;
INSERT INTO public.channels(channels_id,channels_name,channels_created_at,channels_updated_at) VALUES
(1,'WhatsApp',now(),now()),(2,'Instagram',now(),now())
ON CONFLICT(channels_id) DO UPDATE SET channels_name=excluded.channels_name;
COMMIT;


-- >>> 20260730171000_user_profile.sql
BEGIN;

ALTER TABLE public.users
  ADD COLUMN IF NOT EXISTS users_name text,
  ADD COLUMN IF NOT EXISTS users_avatar_path text;

UPDATE public.users AS app_user
SET users_name = COALESCE(
  NULLIF(BTRIM(auth_user.raw_user_meta_data ->> 'full_name'), ''),
  NULLIF(BTRIM(auth_user.raw_user_meta_data ->> 'name'), ''),
  NULLIF(SPLIT_PART(COALESCE(auth_user.email, ''), '@', 1), ''),
  'Usuário'
)
FROM auth.users AS auth_user
WHERE auth_user.id = app_user.auth_user_id
  AND NULLIF(BTRIM(COALESCE(app_user.users_name, '')), '') IS NULL;

COMMENT ON COLUMN public.users.users_name IS 'Nome de exibição editável do usuário interno.';
COMMENT ON COLUMN public.users.users_avatar_path IS 'Caminho privado do avatar no bucket profile-images.';

